// 选择城市（/intentions/cities）—— 「添加求职期望」的次级页 A，多选 0/9。
//
// 版式照规格截图 3 自上而下：✕ 关闭 → 大标题「选择城市」+ 右上 N/9 → 副标题 → 搜索框 →
// 当前/历史访问城市 → 国内/海外热门城市 → 行政区分组 → 底部已选 chips + 保存。
// 正文 JSX（标题/搜索/列表/已选/保存）在两模式共用的 备选城市选择正文（Task 3，core editors
// 展示统一），本页只做两模式的控制映射：把数据源控制映射为同一组 props。
//
// 与 选工作城市（/onboard/city，单选工作城市）的分工：那屏选**一个**主工作城市，
// 这屏选**另外**最多 9 个感兴趣城市，落 意向草稿.感兴趣城市们，互不覆盖。
//
// Task 3（core editors）：两分支都迁移到共用正文 ——
//   Backend 复用 选工作城市 同一套查询钩子（use城市默认页/use城市搜索）：Task 4 起热门区
//   是精选配置的 国内/海外热门城市 两区，默认目录按 CN/TW/HK/MO 四支分页，分组标题 CN 用
//   返回的 admin1_name、港澳台用三个中文固定组名（缺失不入分组，不编造）；「加载更多」沿用
//   现有控件挂在当前可见列表尾。已选按 ID 去重，主城市禁用；ID 映射表由本页维护并保留选中
//   引用（统一收窄为目录选择值），不从可见页按名称反查。
//   Mock 分组种子用 Mock默认城市字典（四直辖市分别列出、港澳台拆三组、无海外长组），局部
//   分页把省份组切片，模拟与 Backend 相同的可见状态；搜索读 Mock城市搜索字典，沿用
//   中文名/规范化拼音 子串匹配（城市拼音 保留此用途）。
//   原 A–Z 分节与右侧字母索引条按批准的视觉差异整体移除（本轮起运行代码对 use城市分组 零消费，按计划约束保留）。

import { useMemo, useRef, useState } from 'react';
import { 次级页外壳 } from '../组件/通用';
import {
  备选城市选择正文,
  type 城市按钮值,
} from '../组件/备选城市选择正文';
import { use导航 } from '../路由/导航钩子';
import { use应用状态 } from '../状态/应用状态';
import { Mock城市搜索字典, Mock默认城市字典 } from '../数据/城市与行业';
import { 国内精选城市, 海外精选城市, 精选城市显示名, 规范精选城市名称 } from '../数据/城市精选';
import { 城市拼音 } from '../数据/城市首字母';
import type { 目录选择值 } from '../数据/招聘数据源类型';
import type { BFFLocationItem } from '../数据/BFF契约';
import { use城市默认页, use城市搜索, 按行政区分组 } from './城市查询钩子';

/** 感兴趣城市多选上限（规格：其他感兴趣城市（N/9））*/
const 城市上限 = 9;

/** Mock 局部分页每次展示的省份组数：切片 Mock默认城市字典，模拟与 Backend 默认页相同的可见状态 */
const Mock每次组数 = 6;

export default function 选择城市() {
  const { 返回 } = use导航();
  const { 状态: 全局, 派发, 数据源模式, 目录查询 } = use应用状态();
  const 是后端 = 数据源模式 === 'backend';

  // 主城市（Backend = 工作城市引用 ID / Mock = 草稿 工作城市 名）：不进入备选列表（可见但禁用）。
  // Task 6：Mock 城名统一按规范名比较（旧草稿「北京」与热门「北京市」同项）。
  const 主城市Id = 是后端 ? 全局.意向草稿.工作城市引用?.id : undefined;
  const Mock主城市 = 规范精选城市名称(全局.意向草稿.工作城市);

  // ── 已选 state ──
  // Backend：目录选择值[]（id + display_name），ID 去重；Mock：string[]，字符串去重。
  // 进页时取草稿里已有的选择；改动先落本地，点保存才写回 —— 中途 ✕ 退出不留脏数据。
  // review-r1 F7：初始选择与 toggle 同一清洗 —— 按 ID 去重并排除主城市（Mock 排除主城市
  // 名、按 9 上限截断），否则历史脏数据让计数虚高、主城市重复占名额。
  // Task 6：显示名经有限映射归一（ID 命中用规范名 / Mock 走别名表），存储不重写。
  const [已选引用, 设已选引用] = useState<目录选择值[]>(() => {
    if (!是后端) return [];
    const seen = new Set<string>();
    const 初始: 目录选择值[] = [];
    for (const 条 of 全局.意向草稿.感兴趣城市引用们 ?? []) {
      if (条.id === 主城市Id || seen.has(条.id)) continue;
      seen.add(条.id);
      初始.push({ id: 条.id, display_name: 精选城市显示名(条.id, 条.display_name) });
    }
    return 初始;
  });
  const [已选, 设已选] = useState<string[]>(() =>
    是后端
      ? 已选引用.map((条) => 条.display_name)
      : 全局.意向草稿.感兴趣城市们
          .map(规范精选城市名称)
          .filter((城) => 城 !== Mock主城市)
          .slice(0, 城市上限),
  );

  // Backend 展示键（= 项 ID）→ 目录选择值 的映射表：本页维护并保留选中引用。
  // 热门/默认页/搜索结果每见一次就登记一次，切回已选 chip 或翻页前的项都能拿到引用，
  // 不按名称反查。进页先装草稿里已有的引用。
  const 项映射 = useRef<Map<string, 目录选择值>>(new Map());
  if (是后端) {
    for (const 条 of 已选引用) 项映射.current.set(条.id, 条);
  }

  // ── 搜索 / 默认目录页查询（Backend 分支，复用 选工作城市 同一套钩子；Mock 分支空操作）──
  const 查询Location = 是后端 ? 目录查询?.查询Location : undefined;
  const { 词, 设词, 结果: 搜索结果项, 搜索中, 下一页游标: 搜索下一页, 加载中: 搜索加载中, 加载更多: 搜索加载更多 } = use城市搜索(查询Location);
  const { 项们: 默认项们, 加载中: 默认加载中, 还有: 默认还有, 加载更多: 默认加载更多 } = use城市默认页(查询Location);

  // Mock 局部分页：省份组切片数量
  const [Mock组数, 设Mock组数] = useState(Mock每次组数);

  const 已选数 = 是后端 ? 已选引用.length : 已选.length;
  const 选满 = 已选数 >= 城市上限;

  const 切换后端 = (项: 目录选择值) => {
    // 主城市不进入备选列表
    if (项.id === 主城市Id) return;
    设已选引用((旧) => {
      if (旧.some((条) => 条.id === 项.id))
        return 旧.filter((条) => 条.id !== 项.id);
      // 选满后未选中的城片已经 disabled，这里是兜底
      if (旧.length >= 城市上限) return 旧;
      return [...旧, 项];
    });
  };

  // Mock 分支切换（保持原逻辑不变）
  const 切换 = (城: string) => {
    设已选((旧) => {
      if (旧.includes(城)) return 旧.filter((条) => 条 !== 城);
      // 选满后未选中的城片已经 disabled，这里是兜底：宁可什么都不发生，也不越过上限
      if (旧.length >= 城市上限) return 旧;
      return [...旧, 城];
    });
  };

  const 保存 = () => {
    if (是后端) {
      派发({
        型: '改意向草稿',
        补丁: {
          感兴趣城市们: 已选引用.map((条) => 条.display_name),
          // 已选引用就是目录选择值（点击时已收窄为 id + display_name），HTTP 层只发 ID
          感兴趣城市引用们: 已选引用,
        },
      });
    } else {
      派发({ 型: '改意向草稿', 补丁: { 感兴趣城市们: 已选 } });
    }
    返回();
  };

  // 中文名和全拼都算命中：输「杭」「hangzhou」「hang」都出杭州（Mock 分支本地过滤，
  // 全集读 Mock城市搜索字典 —— 海外与精选名不因默认页收窄而搜不到）。
  // Task 6：旧中文海外名（别名）与目录规范名都算命中，结果归一到规范名并去重，
  // 同名城市（旧名/规范名两条字典记录）只出一条。
  const 搜索词 = 词.trim().toLowerCase();
  const Mock搜索全集 = useMemo(
    () => Array.from(new Set(Mock城市搜索字典.flatMap((组) => 组.城市))),
    [],
  );
  const 搜索结果 = useMemo(() => {
    if (搜索词 === '') return [];
    const 见过 = new Set<string>();
    const 结果: string[] = [];
    for (const 城 of Mock搜索全集) {
      const 规范名 = 规范精选城市名称(城);
      if (见过.has(规范名)) continue;
      if (
        城.includes(搜索词) ||
        规范名.toLowerCase().includes(搜索词) ||
        (城市拼音[城] ?? '').includes(搜索词)
      ) {
        见过.add(规范名);
        结果.push(规范名);
      }
    }
    return 结果;
  }, [搜索词, Mock搜索全集]);

  // ── 当前可见列表的加载/分页归属（正文只有一套「加载中/还有/加载更多」props）──
  const 在搜索 = 搜索词 !== '';
  const 加载中 = 是后端 ? (在搜索 ? 搜索中 || 搜索加载中 : 默认加载中) : false;
  const 还有 = 在搜索
    ? 是后端 && 搜索下一页 !== null
    : 是后端
      ? 默认还有
      : Mock组数 < Mock默认城市字典.length;
  const 加载更多 = () => {
    if (!是后端) {
      if (!在搜索) 设Mock组数((旧) => 旧 + Mock每次组数);
      return;
    }
    void (在搜索 ? 搜索加载更多() : 默认加载更多());
  };

  /** Backend 城市按钮值：按 ID 识别；主城市禁用；选满后未选中禁用。
   *  展示键 → 目录选择值 登记一次（收窄为 id + display_name，显示名按 ID 归一），切换时按 ID 拿回引用。 */
  const 后端片 = (项: BFFLocationItem): 城市按钮值 => {
    const 名称 = 精选城市显示名(项.id, 项.display_name);
    const 选中 = 已选引用.some((条) => 条.id === 项.id);
    项映射.current.set(项.id, { id: 项.id, display_name: 名称 });
    return {
      键: 项.id,
      名称,
      选中,
      禁用: (选满 && !选中) || 项.id === 主城市Id,
    };
  };

  /** 精选区按钮值：条目本身就是目录选择值，与目录分组/搜索同一 ID 共享选中 */
  const 精选片 = (引用: 目录选择值): 城市按钮值 => {
    const 选中 = 已选引用.some((条) => 条.id === 引用.id);
    项映射.current.set(引用.id, { id: 引用.id, display_name: 引用.display_name });
    return {
      键: 引用.id,
      名称: 引用.display_name,
      选中,
      禁用: (选满 && !选中) || 引用.id === 主城市Id,
    };
  };

  /** Mock 城市按钮值：规范名即稳定键（热门/分省/搜索同名同键） */
  const Mock片 = (城: string): 城市按钮值 => {
    const 名 = 规范精选城市名称(城);
    return {
      键: 名,
      名称: 名,
      选中: 已选.includes(名),
      禁用: 选满 && !已选.includes(名),
    };
  };

  // ── 两模式的展示输入（下面只有一套 props）──
  // 当前/历史访问城市：Backend 用已批准的缺失态「暂未获取定位」，Mock 用演示值上海
  const 位置项们: 城市按钮值[] = 是后端
    ? [{ 键: '暂未获取定位', 名称: '暂未获取定位', 选中: false, 禁用: true }]
    : [Mock片('上海')];
  const 国内热门片们: 城市按钮值[] = 是后端
    ? 国内精选城市.map(精选片)
    : 国内精选城市.map((项) => Mock片(项.display_name));
  const 海外热门片们: 城市按钮值[] = 是后端
    ? 海外精选城市.map(精选片)
    : 海外精选城市.map((项) => Mock片(项.display_name));
  const 分组片们 = 是后端
    ? 按行政区分组(默认项们).map((组) => ({
        键: 组.键,
        标题: 组.键,
        项们: 组.城市们.map((项) => 后端片(项)),
      }))
    : Mock默认城市字典.slice(0, Mock组数).map((组) => ({
        键: 组.省,
        标题: 组.省,
        项们: 组.城市.map(Mock片),
      }));
  const 搜索片们: 城市按钮值[] = 是后端
    ? 搜索结果项.map((项) => 后端片(项))
    : 搜索结果.map(Mock片);
  const 已选片们: 城市按钮值[] = 是后端
    ? 已选引用.map((条) => ({ 键: 条.id, 名称: 条.display_name, 选中: true, 禁用: false }))
    : 已选.map((城) => ({ 键: 城, 名称: 城, 选中: true, 禁用: false }));

  /** 正文只交稳定键：Backend 按 ID 查映射表拿回完整引用，Mock 键即城名 */
  const 切换键 = (键: string) => {
    if (!是后端) {
      切换(键);
      return;
    }
    const 项 = 项映射.current.get(键);
    if (项) 切换后端(项);
  };

  return (
    // 2026-08-24 全站选择风格统一（C1 定稿）：页底改白底
    <次级页外壳 白底>
      <备选城市选择正文
        搜索词={词}
        改搜索词={设词}
        位置项们={位置项们}
        国内热门项们={国内热门片们}
        海外热门项们={海外热门片们}
        分组们={分组片们}
        搜索项们={搜索片们}
        已选项们={已选片们}
        加载中={加载中}
        还有={还有}
        加载更多={加载更多}
        切换={切换键}
        取消={返回}
        保存={保存}
      />
    </次级页外壳>
  );
}